	private static void checkAllocation(Path directory) throws Exception {
		Measurement measured = measure(directory, ORIGINAL_SHAPE);
		long measuredBytes = measured.allocatedBytes();
		// Keep the original absolute budget and eight-predicate workload unchanged.
		System.out.println("COMPACTION_ALLOCATION_BYTES=" + measuredBytes);
		assertThat(measuredBytes).isPositive();
		assertThat(measuredBytes)
				.as("compacting %s existing pages allocated %s bytes (%s bytes/page); budget permits decoded "
						+ "columns, merge buffers, bounded output and one reusable encoder workspace",
						ORIGINAL_SHAPE.pageCount(), measuredBytes, measuredBytes / ORIGINAL_SHAPE.pageCount())
				.isLessThanOrEqualTo(MAX_COMPACTION_ALLOCATION);
	}

	static Measurement measure(Path directory, Shape shape) throws Exception {
		assertThat(ManagementFactory.getThreadMXBean()).isInstanceOf(ThreadMXBean.class);
		ThreadMXBean allocations = (ThreadMXBean) ManagementFactory.getThreadMXBean();
		assertThat(allocations.isThreadAllocatedMemorySupported()).isTrue();
		boolean wasEnabled = allocations.isThreadAllocatedMemoryEnabled();
		if (!wasEnabled) {
			allocations.setThreadAllocatedMemoryEnabled(true);
		}
		Set<Quad> original = model(shape);
		List<Quad> removed = removedRows(shape);
		Set<Quad> expected = new HashSet<>(original);
		expected.removeAll(removed);
		long measuredBytes;
		Map<String, byte[]> oldPages;
		Map<String, byte[]> rewritten;
		try {
			try (Fixture fixture = new Fixture(directory)) {
				try (Transaction writer = fixture.transaction(false)) {
					for (Quad quad : original) {
						assertThat(
								fixture.adjacency.add(writer.txn, quad.subject, quad.predicate, quad.object, 0, true))
										.isTrue();
					}
					fixture.adjacency.compact(writer.txn, true);
					writer.commit();
				}
				try (Transaction oldSnapshot = fixture.transaction(true)) {
					oldPages = pages(fixture, oldSnapshot.txn, LmdbPersistentAdjacency.PAGE_QUADS, shape);
					assertModel(fixture.adjacency, oldSnapshot.txn, original, shape);
					// Warm class initialization and the complete real compaction path. Aborting each writer
					// restores the identical base and prevents trial state from accumulating.
					for (int i = 0; i < WARMUP_COMPACTIONS; i++) {
						try (Transaction writer = fixture.transaction(false)) {
							remove(fixture.adjacency, writer.txn, removed);
							fixture.adjacency.compact(writer.txn, true);
							assertThat(fixture.adjacency.count(writer.txn, true)).isEqualTo(expected.size());
						}
					}
					assertThat(allocations.getCurrentThreadAllocatedBytes()).isGreaterThanOrEqualTo(0);
					try (Transaction writer = fixture.transaction(false)) {
						assertThat(fixture.adjacency.count(writer.txn, true)).isEqualTo(original.size());
						remove(fixture.adjacency, writer.txn, removed);
						assertThat(entries(writer.txn, fixture.adjacency.deltasDbi())).isEqualTo(shape.pageCount());
						long before = allocations.getCurrentThreadAllocatedBytes();
						fixture.adjacency.compact(writer.txn, true);
						measuredBytes = allocations.getCurrentThreadAllocatedBytes() - before;
						// Every correctness and native lifecycle check is outside the allocation interval.
						assertModel(fixture.adjacency, writer.txn, expected, shape);
						assertThat(entries(writer.txn, fixture.adjacency.deltasDbi())).isZero();
						rewritten = pages(fixture, writer.txn, LmdbPersistentAdjacency.PAGE_QUADS - 1, shape);
						assertThat(rewritten.keySet()).containsExactlyInAnyOrderElementsOf(oldPages.keySet());
						rewritten.forEach((key, value) -> assertThat(value)
								.as("every existing page is rewritten without changing its fence: %s", key)
								.isNotEqualTo(oldPages.get(key)));
						writer.commit();
					}
					assertModel(fixture.adjacency, oldSnapshot.txn, original, shape);
					Map<String, byte[]> retained = pages(fixture, oldSnapshot.txn, LmdbPersistentAdjacency.PAGE_QUADS,
							shape);
					oldPages.forEach((key, value) -> assertThat(retained.get(key)).containsExactly(value));
				}
			}
			try (Fixture reopened = new Fixture(directory); Transaction snapshot = reopened.transaction(true)) {
				assertModel(reopened.adjacency, snapshot.txn, expected, shape);
				pages(reopened, snapshot.txn, LmdbPersistentAdjacency.PAGE_QUADS - 1, shape);
				assertThat(entries(snapshot.txn, reopened.adjacency.deltasDbi())).isZero();
			}
			// Return only after model, pinned-snapshot, physical layout, commit, closure, and reopen controls.
			return new Measurement(measuredBytes, orderedPayloads(oldPages), orderedPayloads(rewritten));
		} finally {
			if (!wasEnabled) {
				allocations.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static Set<Quad> model(Shape shape) {
		Set<Quad> result = new HashSet<>();
		for (int predicate = 0; predicate < shape.predicates; predicate++) {
			for (int row = 0; row < shape.rowsPerPredicate; row++) {
				result.add(quad(shape, predicate, row));
			}
		}
		return result;
	}

	private static List<Quad> removedRows(Shape shape) {
		List<Quad> result = new ArrayList<>();
		for (int predicate = 0; predicate < shape.predicates; predicate++) {
			for (int page = 0; page < shape.pagesPerPredicate(); page++) {
				result.add(quad(shape, predicate, page * LmdbPersistentAdjacency.PAGE_QUADS
						+ LmdbPersistentAdjacency.PAGE_QUADS / 2));
			}
		}
		return result;
	}

	private static Quad quad(Shape shape, int predicate, int row) {
		long ordinal = (long) predicate * shape.rowsPerPredicate + row;
		return new Quad(10_000 + ordinal, 20 + predicate, 1_000_000 + ordinal);
	}

	private static void remove(LmdbPersistentAdjacency adjacency, long txn, List<Quad> removed) throws IOException {
		for (Quad quad : removed) {
			assertThat(adjacency.remove(txn, quad.subject, quad.predicate, quad.object, 0, true)).isTrue();
		}
	}

	private static void assertModel(LmdbPersistentAdjacency adjacency, long txn, Set<Quad> expected, Shape shape)
			throws IOException {
		for (boolean incoming : new boolean[] { false, true }) {
			Set<Quad> actual = new HashSet<>();
			try (RecordIterator records = adjacency.scan(txn, -1, -1, -1, -1, true, incoming)) {
				for (long[] quad; (quad = records.next()) != null;) {
					assertThat(quad[3]).isZero();
					assertThat(actual.add(new Quad(quad[0], quad[1], quad[2]))).isTrue();
				}
			}
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		}
		assertThat(adjacency.count(txn, true)).isEqualTo(expected.size());
		assertThat(adjacency.count(txn, false)).isZero();
		assertThat(adjacency.contextCount(txn, 0, true)).isEqualTo(expected.size());
		assertThat(adjacency.contextTotal(txn, 0)).isEqualTo(expected.size());
		for (int predicate = 0; predicate < shape.predicates; predicate++) {
			long id = 20 + predicate;
			assertThat(adjacency.predicateCount(txn, id, true))
					.isEqualTo(expected.stream().filter(quad -> quad.predicate == id).count());
		}
		for (Quad removed : removedRows(shape)) {
			assertThat(adjacency.isIdReferenced(txn, removed.subject)).isEqualTo(expected.contains(removed));
			assertThat(adjacency.isIdReferenced(txn, removed.object)).isEqualTo(expected.contains(removed));
		}
	}

	private static Map<String, byte[]> pages(Fixture fixture, long txn, int expectedQuads, Shape shape)
			throws IOException {
		Map<String, byte[]> pages = new HashMap<>();
		Map<String, Integer> partitionSizes = new HashMap<>();
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, fixture.adjacency.pagesDbi(), pointer));
			long cursor = pointer.get(0);
			try {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack);
				int code = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (code == MDB_SUCCESS) {
					byte[] fence = new byte[(int) key.mv_size()];
					key.mv_data().duplicate().get(fence);
					assertThat(fence).hasSize(33);
					ByteBuffer fields = ByteBuffer.wrap(fence).order(ByteOrder.BIG_ENDIAN);
					int plane = fields.get();
					long predicate = fields.getLong();
					assertThat(plane).isBetween(0, 1);
					assertThat(predicate).isBetween(20L, 20L + shape.predicates - 1);
					PersistentCsfPageCodec.DecodedPage page = PersistentCsfPageCodec.decode(value.mv_data());
					assertThat(page.size()).isEqualTo(expectedQuads);
					assertThat(page.rowCount()).isEqualTo(expectedQuads);
					assertThat(page.rowAt(0)).isEqualTo(fields.getLong());
					assertThat(page.neighborAt(0)).isEqualTo(fields.getLong());
					assertThat(page.contextAt(0)).isEqualTo(fields.getLong());
					assertThat(value.mv_size()).as("bounded serialized output used by the allocation budget")
							.isLessThanOrEqualTo(MAX_ENCODED_PAGE_BYTES);
					byte[] bytes = new byte[(int) value.mv_size()];
					value.mv_data().duplicate().get(bytes);
					assertThat(pages.put(HexFormat.of().formatHex(fence), bytes)).isNull();
					partitionSizes.merge(plane + ":" + predicate, 1, Integer::sum);
					code = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				if (code != MDB_NOTFOUND) {
					E(code);
				}
			} finally {
				mdb_cursor_close(cursor);
			}
		}
		assertThat(pages).hasSize(shape.pageCount());
		assertThat(partitionSizes).hasSize(shape.predicates * 2);
		assertThat(partitionSizes.values()).allMatch(count -> count == shape.pagesPerPredicate());
		return pages;
	}

	private static List<byte[]> orderedPayloads(Map<String, byte[]> pages) {
		// Compare planes and global tuple fences, deliberately excluding the eight-byte predicate field.
		Comparator<String> globalTupleOrder = Comparator.comparing((String fence) -> fence.substring(0, 2))
				.thenComparing(fence -> fence.substring(18));
		return pages.entrySet()
				.stream()
				.sorted(Map.Entry.comparingByKey(globalTupleOrder))
				.map(Map.Entry::getValue)
				.toList();
	}

	record Shape(int predicates, int rowsPerPredicate) {
		Shape {
			assertThat(predicates).isPositive();
			assertThat(rowsPerPredicate).isPositive();
			assertThat(rowsPerPredicate % LmdbPersistentAdjacency.PAGE_QUADS).isZero();
		}

		int pagesPerPredicate() {
			return rowsPerPredicate / LmdbPersistentAdjacency.PAGE_QUADS;
		}

		int pageCount() {
			return Math.multiplyExact(2, Math.multiplyExact(predicates, pagesPerPredicate()));
		}
	}

	record Measurement(long allocatedBytes, List<byte[]> beforePages, List<byte[]> afterPages) {
	}

	private static long entries(long txn, int database) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBStat stat = MDBStat.malloc(stack);
			E(mdb_stat(txn, database, stat));
			return stat.ms_entries();
		}
	}

	private record Quad(long subject, long predicate, long object) {
	}

	private static final class Transaction implements AutoCloseable {
		long txn;

		Transaction(long txn) {
			this.txn = txn;
		}

		void commit() throws IOException {
			long committed = txn;
			txn = 0;
			E(mdb_txn_commit(committed));
		}

		@Override
		public void close() {
			if (txn != 0) {
				mdb_txn_abort(txn);
				txn = 0;
			}
		}
	}

	private static final class Fixture implements AutoCloseable {
		final long environment;
		final LmdbPersistentAdjacency adjacency;

		Fixture(Path directory) throws IOException {
			try (MemoryStack stack = MemoryStack.stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				E(mdb_env_create(pointer));
				environment = pointer.get(0);
				try {
					E(mdb_env_set_maxdbs(environment, 8));
					E(mdb_env_set_mapsize(environment, 128L << 20));
					E(mdb_env_open(environment, directory.toString(), MDB_NOTLS, 0664));
					adjacency = LmdbUtil.writeTransaction(environment, (inner, txn) -> {
						if (LmdbPersistentAdjacency.exists(txn)) {
							return LmdbPersistentAdjacency.openExisting(txn);
						}
						LmdbPersistentAdjacency created = LmdbPersistentAdjacency.open(txn);
						created.initialize(txn);
						return created;
					});
				} catch (IOException | RuntimeException | Error failure) {
					mdb_env_close(environment);
					throw failure;
				}
			}
		}

		Transaction transaction(boolean readOnly) throws IOException {
			try (MemoryStack stack = MemoryStack.stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				E(mdb_txn_begin(environment, 0, readOnly ? MDB_RDONLY : 0, pointer));
				return new Transaction(pointer.get(0));
			}
		}

		@Override
		public void close() {
			mdb_env_close(environment);
		}
	}
